import{_ as o,o as d,c as e,a2 as r}from"./chunks/framework.xCjF2uVY.js";const _=JSON.parse('{"title":"进度 S0–S7","description":"八个阶段各自走到哪、判据是什么、还欠什么","frontmatter":{"title":"进度 S0–S7","description":"八个阶段各自走到哪、判据是什么、还欠什么"},"headers":[],"relativePath":"progress.md","filePath":"progress.md","lastUpdated":1791250821000}'),s={name:"progress.md"};function n(c,t,a,g,i,l){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="进度-s0–s7" tabindex="-1">进度：S0–S7 <a class="header-anchor" href="#进度-s0–s7" aria-label="Permalink to &quot;进度：S0–S7&quot;">​</a></h1><p>计划的终点是「一个房间可自由走动探索（裁剪版）」= <strong>静态场景 + 幻影加农本体 + Link 可行走</strong>。 下表左列是计划里写死的判据，右列是现在盘上站得住的读数 —— 每条都能在 <a href="/nds-site/acceptance.html">验收门读数</a> 里 找到对应的门，每张证据图都能在 <a href="/nds-site/gallery.html">画面证据</a> 里追溯到画它的那份 ROM。</p><table tabindex="0"><thead><tr><th>阶段</th><th>计划判据（原文口径）</th><th>状态</th><th>现在的读数</th></tr></thead><tbody><tr><td><strong>S0</strong> 资产完好 + 身份确认</td><td><code>asset_verify.py</code> 全绿；角色 ROM md5 逐位不变；actor <code>0x52</code> → object ID → object 文件三者钉死</td><td>✅</td><td><code>object:378/0 other:539/1 room:388/0 scene:101/0 static:102/0</code>（dmadata 那条是良性例外）；本体 = <code>object_gnd</code>，Standard 骨架</td></tr><tr><td><strong>S1</strong> 房间 DL → JSON</td><td>逐位复现 694/408、1061/610；<code>G_MTX==0</code>；<code>Σn==unique</code>；母 DL 每条子 DL 的 tri 之和 == 房间总 tri</td><td>✅</td><td><code>room_reconcile.py</code> <strong>32/32</strong>：room_0 694 顶点/408 三角形、room_1 1061/610（opa 608 + xlu 2），两间 <code>G_MTX==0</code>，索引口径 ×2 胜，纹理字节守恒</td></tr><tr><td><strong>S2</strong> 房间纹理烘焙</td><td>纹理总和 ≤ 256 KB；TLUT 数量与 <code>LOADTLUT</code> 计数一致；<code>w*h</code>/<code>lrs+1</code>/<code>dxt</code> 互洽</td><td>✅</td><td>预算门 <strong>13/13</strong>（room_0 13,312 B、room_1 32,512 B）；机内 <code>VRAMMAP=1</code> 实测 22 段 / 66 KB / 零重叠</td></tr><tr><td><strong>S3</strong> 静态场景 ROM</td><td>GPU 读数 == S1 JSON 读数（无丢包）</td><td>✅</td><td>三个机位的 OCR 读数 <code>GPU 1018/1018</code>、<code>verts 1755 tex 22</code>、<code>BOSS 440/440</code>、<code>entry floor -193</code> 与离线现算期望值逐位相同</td></tr><tr><td><strong>S4</strong> 透视相机 + 组剔除</td><td>各 yaw 下可见组与离线 bbox 预测一致；<code>fovy=60°</code>/<code>zFar=1500</code>/<code>fogNear=940</code></td><td>✅</td><td>13 机位逐个过 <code>actual ⊆ predicted</code>；九台剔除孪生主屏 <strong>AE=0</strong>；环境参数四段（ROM 现解 == 头文件 == <code>main.c</code> 字面量 == 量具 <code>--bg</code>）一致</td></tr><tr><td><strong>S5</strong> 碰撞 + 行走</td><td><code>feet_y</code> 常量断言；推向边界被拒坐标与 COL min/max 一致</td><td>✅</td><td>行走预测器自验 FAIL 行 0；四条拒绝分支的<strong>被拒停点设备 == 离线仿真</strong>逐位相同（(15,−3626)/(−760,−2979)/(63,−2904)/(−45,−2904)）</td></tr><tr><td><strong>S5</strong> Link 剪影（走到位的机位）</td><td>— 计划里没有，本轮加的</td><td>✅</td><td>两台机位 CPU 填充 vs 实机差渲染：实机 1598 / 1656 px，位后 IoU <strong>0.878 / 0.906</strong>，一圈 100.0/100.0（这一行<strong>不判绝对摆放</strong>，相机绕玩家 orbit 是它的规范自由度）</td></tr><tr><td><strong>S6</strong> Boss 本体静态网格</td><td>竞技场里看得见幻影加农本体</td><td>✅</td><td>699 顶点/440 三角形解出；剪影门两台位后 IoU <strong>0.801 / 0.796</strong>、最优位移都是 dx=2 在带内；深度归属门近机位 <strong>Link 挡住本体 166 px、本体画进 Link 剪影内 0 px</strong>（<code>--maxover 0</code> 照样 PASS）</td></tr><tr><td><strong>S6</strong> xlu 半透明层</td><td>— 计划里只说&quot;近似&quot;</td><td>⚠ 量到极限</td><td><code>dose</code> 8523 px 100% 落在离线 footprint 内、位后 IoU 0.902（几何归因成立）；深度那侧<strong>共面 ⇒ 平局不可判</strong>（离线距离差 1.71 raw，而 DS 深度一格是 4 raw）</td></tr><tr><td><strong>S7</strong> 运行时 FK（可选项）</td><td>走路姿势随四肢变化</td><td>➖ 不需要</td><td>本体是 Standard 骨架（S0 的结论），FK 不在本场景依赖里</td></tr></tbody></table><h2 id="还欠什么" tabindex="-1">还欠什么 <a class="header-anchor" href="#还欠什么" aria-label="Permalink to &quot;还欠什么&quot;">​</a></h2><ol><li><strong>人眼判决（协议 3）没收到</strong>。数字门全部通过后，&quot;这就是森林 boss 房、纹理是对的、比例是对的&quot;这一句 必须由人看图判定，量具不代替它。素材在 <a href="/nds-site/gallery.html">画面证据</a> 的前两节（验收 ROM 三张 + 七张拼图）， 其中 <code>contact_sheet_2026-10-05_final.png</code> 是<strong>终检图</strong>：四格各只问一件事（整场景 / 本体被 Link 挡住 像不像 / 走到位后比例与四肢 / 转的是相机不是重画场景），一票判完不必翻其余六张分项。</li><li><strong>偏差 4 会被人看见</strong>：本轮按计划不做相机碰撞，房间小、<code>CAM_DIST=90</code> 而眼高只有 60 ⇒ 5975 个合法站立格里 四个朝向各有 <strong>50~55%</strong> 让眼点落进极近几何档，那个档里量具与真机对不齐（色场 WARN 的来源）。</li><li><strong>偏差 1 的归属未证</strong>：desmume 相对 CPU 量具的屏幕错位<strong>不是恒定 +3px</strong>（y180 最优是 dx=0）， 本体那四个独立读数倒是都落在 dx=2。<code>glGetFixed</code> 回读在 desmume 上不响应 ⇒ 上真机第一件事就是复测这条。</li><li><strong>本体无纹理</strong>是范围决定：<code>draw_boss.c</code> 只走顶点色 + 白纹理单位元，所以幻影加农在画面里发白。 <code>object_gnd</code> 确实带 190 SETTIMG / 97 LOADBLOCK / 54 LOADTLUT，要补得走与房间同套管线的另一份口径。</li></ol><h2 id="一句话现状" tabindex="-1">一句话现状 <a class="header-anchor" href="#一句话现状" aria-label="Permalink to &quot;一句话现状&quot;">​</a></h2><p>八阶段全部有数字门通过，<code>--rebuild</code> 67 项(其中 33 台 ROM 逐位复现；本轮唯一未闭合的是&quot;人看图说它是&quot;这件事， 以及三条被明确记为<strong>范围决定 / 量具极限</strong>的偏差（见 <a href="/nds-site/caveats.html">四条已知偏差</a>）。</p>',7)])])}const S=o(s,[["render",n]]);export{_ as __pageData,S as default};
